import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { logout } from '../services/api';
import { AppBar, Toolbar, Typography, Button, Container, Grid, Paper, Menu, MenuItem } from '@mui/material';
import ExamCounts from './count';
import FranchiseList from './FranchiseList';

const Dashboard = () => {
  const navigate = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);  // State for managing the menu anchor

  const handleLogout = async () => {
    try {
      await logout(navigate);
      localStorage.removeItem('token');
      navigate('/login');
    } catch (error) {
      console.error('Logout failed:', error);
      alert('There was an error logging out. Please try again.');
    }
  };

  const handleMenuClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4 }}>
      {/* Menu Bar with AppBar */}
      <AppBar position="sticky">
        <Toolbar>
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            Superadmin Dashboard
          </Typography>
          <Button color="inherit" onClick={handleMenuClick}>
            Menu
          </Button>
          {/* Menu */}
          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
          >
            <MenuItem onClick={() => { navigate('/create-superadmin'); handleMenuClose(); }}>
              Create User
            </MenuItem>
            <MenuItem onClick={() => { navigate('/create-franchise'); handleMenuClose(); }}>
              Create Franchise
            </MenuItem>
            <MenuItem onClick={() => { navigate('/exam-data'); handleMenuClose(); }}>
              Manage Exam Data
            </MenuItem>
            <MenuItem onClick={() => { handleLogout(); handleMenuClose(); }}>
              Logout
            </MenuItem>
          </Menu>
        </Toolbar>
      </AppBar>

      {/* Content Section */}
      {/* <Paper elevation={4} sx={{ p: 4, mt: 4 }}>
        <Typography
          variant="h4"
          align="center"
