        >
          WELCOME TO SUPERADMIN DASHBOARD
        </Typography>

        <Grid container spacing={4} sx={{ mb: 4 }}>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="primary"
              fullWidth
              sx={{ padding: '14px 24px', fontSize: '16px' }}
              onClick={() => navigate('/create-superadmin')}
            >
              Create User
            </Button>
          </Grid>
          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="secondary"
              fullWidth
              sx={{ padding: '14px 24px', fontSize: '16px' }}
              onClick={() => navigate('/create-franchise')}
            >
              Create Franchise
            </Button>
          </Grid>

          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="success"
              fullWidth
              sx={{
                padding: '16px 28px',
                fontSize: '18px',
                backgroundColor: '#4CAF50', // Green color
                '&:hover': {
                  backgroundColor: '#45a049', // Darker green on hover
                  boxShadow: '0px 4px 20px rgba(0, 0, 0, 0.2)', // Hover effect with shadow
                },
              }}
              onClick={() => navigate('/exam-data')} // This navigates to the exam data page
            >
              Manage Exam Data
            </Button>
          </Grid>

          <Grid item xs={12} md={3}>
            <Button
              variant="contained"
              color="error"
              fullWidth
